+fn main() {
+    let args = Docopt::new(USAGE).and_then(|d| d.decode())
+                                 .unwrap_or_else(|e| e.exit());
+    match run(&args) {
+        Ok(count) if count == 0 => process::exit(1),
+        Ok(_) => process::exit(0),
+        Err(err) => {
+            let _ = writeln!(&mut io::stderr(), "{}", err);
+            process::exit(1);
+        }
+    }
+}
